(function () {
  const stages = ["Applied", "Screening", "Pre-screen Call", "First Interview", "Offer", "Hired", "Rejected"];
  const initialState = {
    route: "dashboard",
    jobs: [{ id: "job-1", title: "Tech Lead / Senior Developer", department: "Engineering", status: "Open", applications: 8 }],
    candidates: [{ id: "cand-1", name: "Narin Chaiyapruk", source: "Referral", stage: "Screening", score: 8.2, job: "Tech Lead / Senior Developer" }],
    notices: [],
    scenario: "normal",
    trackerView: "kanban"
  };
  let state = structuredClone(initialState);
  const app = document.querySelector("#app");

  const esc = (value) => String(value).replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char]));
  const navItems = ["dashboard", "jobs", "candidates", "applications", "interviews"];
  const title = { dashboard: "Today at a glance", jobs: "Jobs", candidates: "Candidates", applications: "Applicant tracker", interviews: "Interviews" };

  function shell(content) {
    app.innerHTML = `<div class="app-shell"><aside class="sidebar"><div class="brand">Talent<span>Flow</span></div><nav class="nav" aria-label="Primary navigation">${navItems.map((item) => `<button class="${state.route === item ? "active" : ""}" data-route="${item}">${title[item]}</button>`).join("")}</nav><div class="sidebar-footer">Low-fi validation prototype<br>Fixture state only</div></aside><main class="main"><div class="topbar"><div><div class="eyebrow">Recruiting workspace</div><h1>${title[state.route] || "TalentFlow"}</h1><p class="muted">Make the next HR decision clear.</p></div><div class="toolbar"><button class="button ghost" data-reset>Reset fixture</button><span class="status">Prototype</span></div></div>${content}</main></div>`;
    bindGlobal();
  }

  function bindGlobal() {
    document.querySelectorAll("[data-route]").forEach((button) => button.addEventListener("click", () => navigate(button.dataset.route)));
    document.querySelector("[data-reset]")?.addEventListener("click", () => { state = structuredClone(initialState); render(); toast("Fixture state reset"); });
  }

  function navigate(route) { state.route = route; render(); }
  function toast(message) { const node = document.createElement("div"); node.className = "toast"; node.textContent = message; document.body.append(node); setTimeout(() => node.remove(), 2200); }
  function modal(titleText, body, actions = "") { const node = document.createElement("div"); node.className = "modal-backdrop"; node.innerHTML = `<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(titleText)}"><div class="split"><div><div class="eyebrow">Review action</div><h2>${esc(titleText)}</h2></div><button class="button ghost" data-close>Close</button></div>${body}<div class="modal-actions">${actions}</div></section>`; document.body.append(node); node.querySelector("[data-close]").addEventListener("click", () => node.remove()); return node; }

  function renderDashboard() {
    return `<div class="grid four"><button class="panel metric" data-route="jobs"><small>Open jobs</small><strong>1</strong><small>1 needs attention</small></button><button class="panel metric" data-route="applications"><small>Applications</small><strong>8</strong><small>Across 7 stages</small></button><button class="panel metric" data-route="candidates"><small>Pending AI review</small><strong>3</strong><small>Human approval required</small></button><button class="panel metric" data-route="interviews"><small>Interviews this week</small><strong>4</strong><small>1 conflict flagged</small></button></div><div class="section grid two"><section class="panel"><div class="split"><div><h2>Needs attention</h2><p class="muted small">Actions that keep hiring moving.</p></div><span class="status warn">3 items</span></div><div class="list"><button class="list-row button ghost" data-route="candidates"><span><strong>Review AI screening</strong><br><span class="muted small">3 candidates waiting for HR</span></span><span>→</span></button><button class="list-row button ghost" data-route="interviews"><span><strong>Resolve interview conflict</strong><br><span class="muted small">Tech Lead / Narin Chaiyapruk</span></span><span>→</span></button></div></section><section class="panel"><h2>Active position</h2><div class="list"><div class="list-row"><span><strong>Tech Lead / Senior Developer</strong><br><span class="muted small">Engineering · 8 applications</span></span><span class="status">Open</span></div><div class="list-row"><span><strong>Pipeline movement</strong><br><span class="muted small">2 candidates moved this week</span></span><span class="score">+2</span></div></div></section></div>`;
  }
  function renderJobs() { const job = state.jobs[0]; return `<div class="toolbar"><button class="button primary" data-create-job>Create job</button><button class="button" data-route="candidates">Open discovery</button></div><div class="section panel"><div class="list"><button class="list-row button ghost" data-job-detail><span><strong>${esc(job.title)}</strong><br><span class="muted small">${esc(job.department)} · ${job.applications} applications</span></span><span class="status">${job.status}</span></button></div></div>`; }
  function renderCandidates() { return `<div class="toolbar"><button class="button primary" data-discovery>Run discovery fixture</button><button class="button" data-screening>Open screening fixture</button><button class="button" data-upload-cv>Upload or paste CV</button></div><div class="section panel"><div class="split"><div><h2>Candidate review</h2><p class="muted small">Evidence first. HR approves before pipeline entry.</p></div><span class="status">3 pending</span></div><div class="list"><div class="list-row"><span><strong>Narin Chaiyapruk</strong><br><span class="muted small">Referral · Tech Lead / Senior Developer</span></span><span class="score">8.2</span><button class="button" data-candidate-review>Review</button></div><div class="list-row"><span><strong>Demo duplicate candidate</strong><br><span class="muted small">LinkedIn · possible match</span></span><span class="status warn">Duplicate</span><button class="button" data-duplicate>Resolve</button></div></div></div>`; }
  function renderApplications() { const controls = `<div class="toolbar"><button class="button ${state.trackerView === "kanban" ? "primary" : ""}" data-view="kanban">Kanban</button><button class="button ${state.trackerView === "table" ? "primary" : ""}" data-view="table">Table</button><select aria-label="Filter by stage"><option>All stages</option>${stages.map((stage) => `<option>${stage}</option>`).join("")}</select><select aria-label="Filter by source"><option>All sources</option><option>Referral</option><option>LinkedIn</option></select></div>`; if (state.trackerView === "table") return `${controls}<div class="section panel"><div class="list">${state.candidates.map((candidate) => `<div class="list-row"><span><strong>${esc(candidate.name)}</strong><br><span class="muted small">${esc(candidate.job)} · ${esc(candidate.source)}</span></span><span>${esc(candidate.stage)}</span><span class="score">${candidate.score}</span><button class="button" data-candidate-card="${candidate.id}">Open</button></div>`).join("")}</div></div>`; return `${controls}<div class="section kanban">${stages.map((stage) => `<section class="kanban-column"><h3>${stage}</h3>${state.candidates.filter((candidate) => candidate.stage === stage).map((candidate) => `<button class="candidate-card" data-candidate-card="${candidate.id}"><strong>${esc(candidate.name)}</strong><br><span class="muted small">${esc(candidate.source)}</span><br><span class="score">${candidate.score}</span></button>`).join("") || `<div class="muted small">No candidates</div>`}</section>`).join("")}</div>`; }
  function renderInterviews() { return `<div class="toolbar"><button class="button primary" data-schedule>Schedule interview</button></div><div class="section grid two"><section class="panel"><div class="split"><div><h2>This week</h2><p class="muted small">Week view · Bangkok timezone</p></div><span class="status warn">1 conflict</span></div><div class="list"><div class="list-row"><span><strong>Pre-screen Call · Narin Chaiyapruk</strong><br><span class="muted small">Thu 14 Aug · 10:00–10:30</span></span><button class="button" data-interview-detail>Open</button><button class="button" data-reschedule>Reschedule</button><button class="button danger" data-cancel-interview>Cancel</button></div></div></section><section class="panel"><h2>Sync status</h2><div class="state-box warning"><strong>Calendar sync needs review</strong><p class="small">One fixture event failed to sync. Retry keeps the same idempotency key.</p><button class="button" data-sync-retry>Retry sync</button></div></section></div>`; }

  function bindRoute() {
    document.querySelectorAll("[data-route]").forEach((button) => button.addEventListener("click", () => navigate(button.dataset.route)));
    document.querySelector("[data-create-job]")?.addEventListener("click", () => { const node = modal("Create job", `<form class="form" id="job-form"><div class="field"><label for="job-title">Job title</label><input id="job-title" required placeholder="e.g. Tech Lead" /></div><div class="field"><label for="job-jd">Job description</label><textarea id="job-jd" required placeholder="Paste JD here..."></textarea></div><div class="state-box"><strong>Criteria preview</strong><p class="small">Required skills and experience will appear here for HR review before saving.</p></div></form>`, `<button class="button" data-close>Cancel</button><button class="button primary" data-save-job>Save draft</button>`); node.querySelector("[data-save-job]").addEventListener("click", () => { const form = node.querySelector("#job-form"); if (!form.reportValidity()) return; state.jobs.unshift({ id: `job-${Date.now()}`, title: form.querySelector("#job-title").value, department: "New department", status: "Draft", applications: 0 }); node.remove(); render(); toast("Draft saved"); }); node.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => node.remove())); });
    document.querySelector("[data-job-detail]")?.addEventListener("click", () => { const node = modal("Tech Lead / Senior Developer", `<div class="tabs"><button class="active">Overview</button><button>Criteria</button><button>Applications</button><button>Discovery</button><button>Activity</button></div><p class="muted">Engineering · Open · 8 applications</p><div class="state-box"><strong>Next action</strong><p class="small">Review 3 AI screenings before moving candidates forward.</p></div>`, `<button class="button" data-close>Close</button><button class="button danger" data-close-job>Close job</button>`); node.querySelector("[data-close-job]").addEventListener("click", () => { node.remove(); const confirm = modal("Close job", `<div class="field"><label for="close-reason">Reason</label><select id="close-reason" required><option value="">Select reason</option><option>Hired</option><option>Business priority changed</option><option>Cancelled</option></select></div>`, `<button class="button" data-close>Cancel</button><button class="button danger" data-confirm-close>Confirm close</button>`); confirm.querySelector("[data-confirm-close]").addEventListener("click", () => { if (!confirm.querySelector("#close-reason").value) return; state.jobs[0].status = "Closed"; confirm.remove(); render(); toast("Job closed with reason"); }); confirm.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => confirm.remove())); }); node.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => node.remove())); });
    document.querySelector("[data-discovery]")?.addEventListener("click", () => { const node = modal("Discovery fixture", `<div class="state-box"><strong>Query preview</strong><p class="small">site:linkedin.com/in TypeScript PostgreSQL "Tech Lead" Bangkok</p></div><div class="section list"><div class="list-row"><span><strong>Araya K.</strong><br><span class="muted small">LinkedIn · TypeScript, AWS · 6 years</span></span><span class="score">8.7</span><button class="button" data-approve>Approve</button><button class="button ghost" data-reject>Reject</button></div><div class="list-row"><span><strong>Demo duplicate candidate</strong><br><span class="muted small">JobThai · matching email</span></span><span class="status warn">Duplicate</span><button class="button" data-duplicate>Resolve</button></div></div>`, `<button class="button" data-close>Cancel</button><button class="button" data-provider-fail>Simulate provider failure</button>`); node.querySelector("[data-approve]").addEventListener("click", () => { node.remove(); state.candidates.push({ id: "cand-2", name: "Araya K.", source: "LinkedIn", stage: "Applied", score: 8.7, job: "Tech Lead / Senior Developer" }); toast("Candidate approved; application created once"); }); node.querySelector("[data-reject]").addEventListener("click", () => { node.remove(); const reject = modal("Reject discovery result", `<div class="field"><label for="discovery-reason">Reason</label><textarea id="discovery-reason" required placeholder="Why is this result not suitable?"></textarea></div>`, `<button class="button" data-close>Cancel</button><button class="button danger" data-confirm-reject>Reject result</button>`); reject.querySelector("[data-confirm-reject]").addEventListener("click", () => { if (!reject.querySelector("#discovery-reason").value) return; reject.remove(); toast("Discovery result rejected"); }); reject.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => reject.remove())); }); node.querySelector("[data-provider-fail]").addEventListener("click", () => { node.querySelector(".section").innerHTML = `<div class="state-box error"><strong>Provider unavailable</strong><p class="small">DISCOVERY_PROVIDER_UNAVAILABLE · Request ID req_demo_001</p><button class="button" data-retry-discovery>Retry</button></div>`; node.querySelector("[data-retry-discovery]").addEventListener("click", () => { node.remove(); toast("Discovery retry completed"); }); }); node.querySelector("[data-duplicate]").addEventListener("click", () => { node.remove(); const duplicate = modal("Resolve duplicate", `<div class="state-box warning"><strong>Possible duplicate</strong><p class="small">This result matches an existing candidate by email. Compare source data before approving.</p></div><div class="section"><p><strong>Existing:</strong> Narin Chaiyapruk</p><p><strong>Source:</strong> Referral</p></div>`, `<button class="button" data-close>Keep separate</button><button class="button primary" data-close>Link candidate</button>`); duplicate.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => duplicate.remove())); }); node.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => node.remove())); });
    document.querySelector("[data-screening]")?.addEventListener("click", () => showScreening());
    document.querySelector("[data-candidate-review]")?.addEventListener("click", () => showScreening());
    document.querySelector("[data-upload-cv]")?.addEventListener("click", () => { const node = modal("Upload resume", `<form class="form" id="resume-form"><div class="field"><label for="resume-file">PDF resume</label><input id="resume-file" type="file" accept="application/pdf,text/plain" /></div><div class="field"><label for="resume-text">Or paste plain text</label><textarea id="resume-text" placeholder="Paste resume text..."></textarea></div><div class="state-box"><strong>Privacy</strong><p class="small">CV is stored in a private bucket. AI output is advisory and requires HR review.</p></div></form>`, `<button class="button" data-close>Cancel</button><button class="button primary" data-run-screening>Run screening</button>`); node.querySelector("[data-run-screening]").addEventListener("click", () => { const form = node.querySelector("#resume-form"); if (!form.querySelector("#resume-file").files.length && !form.querySelector("#resume-text").value.trim()) return; node.remove(); showScreening(); }); node.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => node.remove())); });
    document.querySelector("[data-duplicate]")?.addEventListener("click", () => modal("Resolve duplicate", `<div class="state-box warning"><strong>Possible duplicate</strong><p class="small">This result matches an existing candidate by email. Compare source data before approving.</p></div><div class="section"><p><strong>Existing:</strong> Narin Chaiyapruk</p><p><strong>Source:</strong> Referral</p></div>`, `<button class="button" data-close>Keep separate</button><button class="button primary" data-close>Link candidate</button>`));
    document.querySelector("[data-schedule]")?.addEventListener("click", () => showScheduler());
    document.querySelector("[data-interview-detail]")?.addEventListener("click", () => showScheduler());
    document.querySelector("[data-reschedule]")?.addEventListener("click", () => showScheduler());
    document.querySelector("[data-cancel-interview]")?.addEventListener("click", () => { const reason = prompt("Cancellation reason (required)"); if (reason?.trim()) toast("Interview cancelled and tracker updated"); });
    document.querySelector("[data-sync-retry]")?.addEventListener("click", () => toast("Retry queued with same idempotency key"));
    document.querySelectorAll("[data-candidate-card]").forEach((button) => button.addEventListener("click", () => showCandidateDrawer(button.dataset.candidateCard)));
    document.querySelectorAll("[data-view]").forEach((button) => button.addEventListener("click", () => { state.trackerView = button.dataset.view; render(); }));
  }
  function showScreening() { const node = modal("AI resume screening", `<div class="state-box"><strong>Recommendation: review</strong><p class="small">AI output validated. HR decision required.</p></div><div class="grid two section"><div class="panel"><h3>Skills fit</h3><span class="score">8/10</span><p class="muted small">TypeScript and PostgreSQL match required skills.</p></div><div class="panel"><h3>Experience fit</h3><span class="score">7/10</span><p class="muted small">Leadership evidence present; scale is unclear.</p></div><div class="panel"><h3>Communication</h3><span class="score">6/10</span><p class="muted small">Insufficient evidence from resume.</p></div><div class="panel"><h3>Questions</h3><p class="small">Ask about team size, delivery ownership, and stakeholder communication.</p></div></div><details class="section"><summary>AI metadata</summary><p class="muted small">Provider: OpenRouter · Model: Claude Sonnet · Prompt: resume-screening.v1 · Schema: v1 · Validation: passed</p></details>`, `<button class="button" data-close>Request review</button><button class="button primary" data-accept>Accept recommendation</button><button class="button danger" data-override>Override</button><button class="button ghost" data-invalid>Simulate invalid output</button>`); node.querySelector("[data-accept]").addEventListener("click", () => { node.remove(); toast("Recommendation accepted; HR decision recorded"); }); node.querySelector("[data-override]").addEventListener("click", () => { const reason = prompt("Override reason (required)"); if (reason?.trim()) { node.remove(); toast("AI recommendation overridden with reason"); } }); node.querySelector("[data-invalid]").addEventListener("click", () => { node.querySelector(".state-box").className = "state-box error"; node.querySelector(".state-box").innerHTML = `<strong>AI_OUTPUT_INVALID</strong><p class="small">Schema validation failed. No score was persisted.</p><button class="button" data-retry-ai>Retry</button>`; node.querySelector("[data-retry-ai]").addEventListener("click", () => { node.remove(); showScreening(); }); }); node.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => node.remove())); }
  function showScheduler() { const node = modal("Schedule interview", `<form class="form" id="schedule-form"><div class="field"><label>Candidate</label><input value="Narin Chaiyapruk" readonly /></div><div class="grid two"><div class="field"><label for="date">Date</label><input id="date" type="date" required /></div><div class="field"><label for="time">Time</label><input id="time" type="time" required /></div></div><div class="field"><label for="questions">Additional questions</label><textarea id="questions">Ask about system design ownership and team leadership.</textarea></div><div class="state-box warning"><strong>Conflict preview</strong><p class="small">Fixture conflict at Thu 14 Aug, 10:00–10:30. Try another time.</p></div></form>`, `<button class="button" data-close>Cancel</button><button class="button primary" data-schedule-save>Check and create</button><button class="button ghost" data-sync-fail>Simulate sync failure</button>`); node.querySelector("[data-schedule-save]").addEventListener("click", () => { const form = node.querySelector("#schedule-form"); if (!form.reportValidity()) return; const time = form.querySelector("#time").value; if (time === "10:00") { node.querySelector(".state-box").innerHTML = `<strong>INTERVIEW_CONFLICT</strong><p class="small">This time overlaps another appointment. Suggested alternatives: 11:00 or 14:30.</p>`; return; } node.remove(); toast("Appointment created; Google Meet sync complete"); }); node.querySelector("[data-sync-fail]").addEventListener("click", () => { node.querySelector(".state-box").className = "state-box error"; node.querySelector(".state-box").innerHTML = `<strong>Calendar sync failed</strong><p class="small">CALENDAR_PROVIDER_ERROR · Local appointment is not marked fully synced.</p><button class="button" data-retry-calendar>Retry with same idempotency key</button>`; node.querySelector("[data-retry-calendar]").addEventListener("click", () => { node.remove(); toast("Calendar retry succeeded; no duplicate event created"); }); }); node.querySelectorAll("[data-close]").forEach((button) => button.addEventListener("click", () => node.remove())); }
  function showCandidateDrawer(id) { const candidate = state.candidates.find((item) => item.id === id); const node = document.createElement("div"); node.className = "drawer-backdrop"; node.innerHTML = `<aside class="drawer"><div class="split"><div><div class="eyebrow">Application detail</div><h2>${esc(candidate.name)}</h2><p class="muted">${esc(candidate.job)}</p></div><button class="button ghost" data-close>Close</button></div><div class="section state-box"><strong>Current stage: ${esc(candidate.stage)}</strong><p class="small">Updated by HR · today 09:42</p></div><div class="section"><h3>Move stage</h3><select aria-label="Move stage">${stages.map((stage) => `<option ${stage === candidate.stage ? "selected" : ""}>${stage}</option>`).join("")}</select><button class="button primary" data-stage-save>Save stage</button><button class="button" data-stale>Simulate stale update</button><button class="button danger" data-reject-application>Reject application</button></div><div class="section"><h3>Activity</h3><div class="list"><div class="list-row small"><span>Screening completed</span><span class="muted">Today</span></div><div class="list-row small"><span>Application created</span><span class="muted">Yesterday</span></div></div></div></aside>`; document.body.append(node); node.querySelector("[data-close]").addEventListener("click", () => node.remove()); node.querySelector("[data-stage-save]").addEventListener("click", () => { node.remove(); toast("Stage updated; pipeline event recorded"); }); node.querySelector("[data-reject-application]").addEventListener("click", () => { const reason = prompt("Rejection reason (required)"); if (reason?.trim()) { node.remove(); toast("Application rejected with reason"); } }); node.querySelector("[data-stale]").addEventListener("click", () => { node.querySelector(".state-box").className = "state-box error"; node.querySelector(".state-box").innerHTML = `<strong>409 Conflict</strong><p class="small">This application changed by another user. Refresh before updating.</p><button class="button" data-refresh>Refresh</button>`; node.querySelector("[data-refresh]").addEventListener("click", () => { node.remove(); render(); toast("Application refreshed"); }); }); }

  function render() { let content = renderDashboard(); if (state.route === "jobs") content = renderJobs(); if (state.route === "candidates") content = renderCandidates(); if (state.route === "applications") content = renderApplications(); if (state.route === "interviews") content = renderInterviews(); shell(content); bindRoute(); }
  render();
})();
